G=lambda s,dot=True,col='currentColor': f'<svg width="{s}" height="{s}" viewBox="0 0 24 24" style="flex:none"><path d="M4 18 12 10l8 8" fill="none" stroke="{col}" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/>' + ('<circle cx="19.5" cy="4.5" r="3.5" fill="#FF3D8B"/>' if dot else '') + '</svg>'
ICON=lambda s: f'<svg width="{s}" height="{s}" viewBox="0 0 100 100"><rect width="100" height="100" rx="24" fill="#0A0A0A"/><path d="M27 66 50 42l23 24" fill="none" stroke="#FFF" stroke-width="11" stroke-linecap="round" stroke-linejoin="round"/><circle cx="73" cy="27" r="10" fill="#FF3D8B"/></svg>'
CSS='''<style>
@font-face{font-family:Geist;font-weight:100 900;src:url(../../../assets/fonts/geist-latin.woff2)}
@font-face{font-family:JBM;font-weight:100 900;src:url(../../../assets/fonts/jetbrains-mono-latin.woff2)}
*{box-sizing:border-box}body{margin:0;width:1280px;height:800px;overflow:hidden;font-family:Geist,system-ui;background:#0a0a0a;color:#fafafa;-webkit-font-smoothing:antialiased}
.frame{display:flex;height:800px}.cap{width:430px;padding:72px 48px 72px 64px;display:flex;flex-direction:column;gap:22px}
.cap h1{font-size:44px;line-height:50px;font-weight:650;letter-spacing:-.02em;margin:0}.cap p{font-size:18px;line-height:28px;color:#a3a3a3;margin:0}
.brand{display:flex;gap:10px;align-items:center;font:700 18px JBM}.stage{flex:1;padding:56px 56px 56px 0;display:flex;align-items:center}
.win{background:#fff;color:#0a0a0a;border-radius:14px;width:100%;height:100%;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 30px 80px rgba(0,0,0,.5)}
.bar{height:40px;background:#f0f0f0;display:flex;align-items:center;gap:8px;padding:0 14px}.d{width:11px;height:11px;border-radius:6px}
.url{margin-left:12px;background:#fff;border-radius:6px;padding:3px 12px;font:12px JBM;color:#6b6b6b;width:300px}
.mono{font-family:JBM}.mut{color:#6b6b6b}.tag{font:11px JBM;padding:1px 6px;border-radius:4px}
</style>'''
def page(body): return '<!doctype html><meta charset=utf-8>'+CSS+body
cap=lambda h,p: f'<div class="cap"><div class="brand">{G(20,True,"#fafafa")}headsup</div><div style="flex:1"></div><h1>{h}</h1><p>{p}</p><div style="flex:1"></div></div>'
note=lambda t,body,src: f'<label style="display:grid;grid-template-columns:18px auto 1fr;gap:4px 10px;align-items:baseline;font-size:14px;line-height:20px"><span style="width:14px;height:14px;border-radius:3px;background:#e0186c;display:inline-flex;align-items:center;justify-content:center;transform:translateY(2px)"><svg width="10" height="10" viewBox="0 0 10 10"><path d="M2 5.2 4.2 7.4 8 2.8" fill="none" stroke="#fff" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span class="tag" style="{"color:#1f7a3e;background:#e3f5e9" if t=="how" else "color:#1d5fd1;background:#e4ecfb"}">{"how you work" if t=="how" else "fact"}</span><span>{body}</span><span></span><span></span><span class="mut" style="font-size:12px">{src}</span></label>'
s1=page('<div class="frame">'+cap('Context from your other AIs, only when it helps.','Type as usual. When a question needs something Claude, Claude Code or Codex knows about you, headsup shows the notes it would add. Untick any, then send.')+f'''<div class="stage"><div class="win"><div class="bar"><span class="d" style="background:#ff5f57"></span><span class="d" style="background:#febc2e"></span><span class="d" style="background:#28c840"></span><span class="url">chatgpt.com</span></div>
<div style="flex:1;display:flex;flex-direction:column;justify-content:flex-end;padding:28px 40px;gap:14px;background:#fff"><div style="align-self:flex-end;max-width:70%;border-radius:20px;background:#f4f4f4;padding:12px 18px;font-size:15px">Can you help me announce Quorum v0.3?</div><div style="font-size:15px;line-height:23px;color:#333;max-width:85%">Sure. Where will you post it, and who is it for?</div><div style="flex:1"></div>
<div style="border:1px solid #e5e5e5;border-radius:14px;padding:16px 18px;display:flex;flex-direction:column;gap:12px;box-shadow:0 12px 32px rgba(0,0,0,.08)">
<div style="display:flex;gap:10px;align-items:center"><b class="mono" style="display:flex;gap:6px;align-items:center;color:#e0186c">{G(14,True,"#e0186c")}heads-up</b><span>2 notes will go in with this message</span></div>
{note("how","Writes launch posts short and plain: under 80 words, no emoji, ends with a question.","Claude · personal")}
{note("fact","Quorum v0.3 adds recurring meetings and Google Calendar sync.","Claude Code (quorum) · personal")}
<p class="mut" style="font-size:12px;margin:0">Goes at the end of your message as a short context block · untick to leave one out</p></div>
<div style="display:flex;justify-content:flex-end"><span class="mono" style="display:inline-flex;gap:6px;align-items:center;font-size:12px;padding:3px 10px;border-radius:999px;background:#fde7f0">{G(12)}2 notes · 2 tools</span></div>
<div style="border-radius:24px;background:#f4f4f4;padding:16px 22px;font-size:16px">Write a LinkedIn post about launching my side project</div>
</div></div></div></div>''')
row=lambda t,sub,on: f'<div style="display:flex;justify-content:space-between;gap:16px"><div><div style="font-weight:500">{t}</div><div style="color:#8f8f8f;font-size:12px;line-height:17px">{sub}</div></div><span style="flex:none;width:32px;height:18px;border-radius:9px;background:{"#ff3d8b" if on else "#262626"};position:relative"><span style="position:absolute;top:2px;left:{16 if on else 2}px;width:14px;height:14px;border-radius:7px;background:#fff"></span></span></div>'
hr='<div style="height:1px;background:#262626"></div>'
sec=lambda t: f'<div class="mono" style="font-size:11px;letter-spacing:.06em;color:#8f8f8f">{t}</div>'
pop=f'''<div style="width:380px;background:#0a0a0a;border:1px solid #262626;border-radius:14px;padding:18px;display:flex;flex-direction:column;gap:14px;font-size:13px;line-height:18px;box-shadow:0 30px 80px rgba(0,0,0,.6)">
<div style="display:flex;justify-content:space-between"><span class="mono" style="display:flex;gap:7px;align-items:center;font-weight:700">{G(14,True,"#fafafa")}headsup</span><span style="display:flex;gap:6px;align-items:center;color:#8f8f8f;font-size:12px"><span style="width:7px;height:7px;border-radius:4px;background:#4ade80"></span>Connected</span></div>
<span style="color:#8f8f8f;font-size:12px">214 notes on this computer · sharing: Balanced</span>{hr}
{sec("ON THIS SITE")}{row("Add context on chatgpt.com","Shows the headsup mark when your notes can help.",True)}{hr}
{sec("KEEP IN SYNC")}{row("Capture new ChatGPT chats","Phone and desktop app chats too. Caught up 10:40.",True)}{row("Capture new Claude chats","Caught up 09:12.",True)}{row("Keep “About me” current","12 lines in ChatGPT and Claude. <span style=\"color:#ff3d8b\">See what it writes →</span>",True)}{hr}
<span style="color:#ff3d8b;font-size:13px;font-weight:500">Share my card →</span>
<span style="color:#8f8f8f;font-size:11px;line-height:16px">Notes stay on this computer. See what was shared where: <span class="mono">headsup review</span></span></div>'''
s2=page('<div class="frame">'+cap('Your notes stay on your computer.','Plain Markdown files, managed by the free headsup app. No server, no account, no analytics. Work and personal stay apart: work facts wait for your OK before they cross over.')+f'<div class="stage" style="justify-content:center;background:radial-gradient(circle at 60% 50%,#1a0a12,#0a0a0a 70%)">{pop}</div></div>')
hl=lambda t: f'<span style="color:#ff3d8b;font-weight:700;text-decoration:underline">{t}</span>'
card=lambda title,head,body,on: f'<div style="flex:1;min-height:440px;background:#141414;border:1px solid {"#ff3d8b" if on else "#262626"};border-radius:14px;padding:24px;display:flex;flex-direction:column;gap:14px"><div class="mono" style="font-size:12px;letter-spacing:.06em;color:{"#ff3d8b" if on else "#8f8f8f"}">{title}</div><div class="mono" style="font-size:14px;color:#a3a3a3">› help me write a cover letter for a PM internship</div>{head}<div style="font-size:16px;line-height:26px;white-space:pre-wrap">{body}</div></div>'
s3=page('<div class="frame">'+cap('Same question. Now it knows you.','What you built lives in Claude Code; ChatGPT never saw it. headsup brings it over before the answer is written, so ChatGPT writes instead of asking.')+'<div class="stage" style="gap:20px;align-items:center">'+card('WITHOUT HEADSUP','', "I\'d be glad to help! To make it stand out, tell me a bit about you:\n\n1. What projects have you built?\n2. Any results you can point to?\n3. Which company is it for?",False)+card('WITH HEADSUP',f'<div class="mono" style="font-size:13px;display:flex;gap:6px;align-items:center"><span style="color:#ff3d8b;display:flex;gap:6px;align-items:center;white-space:nowrap">{G(13,True,"#ff3d8b")}heads-up</span><span style="color:#8f8f8f;white-space:nowrap">3 notes from Claude Code</span></div>',f"Dear hiring team,\n\nThis summer I interned on {hl('the payments team at Northwind')}, where I {hl('shipped payout retries that cut failed payouts by 30%')}. On the side I built {hl('Quorum, a web app that finds a meeting time for student clubs')}. ...",True)+'</div></div>')
promo='<!doctype html><meta charset=utf-8>'+CSS.replace('width:1280px;height:800px','width:440px;height:280px')+f'<div style="height:280px;display:flex;flex-direction:column;justify-content:center;gap:16px;padding:0 36px;background:radial-gradient(circle at 85% 20%,#2a0d1b,#0a0a0a 60%)"><div style="display:flex;gap:14px;align-items:center">{ICON(56)}<span class="mono" style="font-size:30px;font-weight:700">headsup</span></div><div style="font-size:21px;line-height:28px;font-weight:600">Gives your AI a heads-up<br>before it answers.</div></div>'
for n,h in [('screenshot-1-composer',s1),('screenshot-2-popup',s2),('screenshot-3-before-after',s3),('promo-small',promo)]: open(n+'.html','w').write(h)
